const rand=(a,b)=>a+Math.random()*(b-a);
const randInt=(a,b)=>Math.floor(rand(a,b+1));
const lerp=(a,b,t)=>a+(b-a)*t;
const lerp2=(a,b,t)=>[lerp(a[0],b[0],t),lerp(a[1],b[1],t)];
function catmull(p0,p1,p2,p3,t){
  const t2=t*t,t3=t2*t;
  return 0.5*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t2+(-p0+3*p1-3*p2+p3)*t3);
}
function catmull2(p0,p1,p2,p3,t){return [catmull(p0[0],p1[0],p2[0],p3[0],t),catmull(p0[1],p1[1],p2[1],p3[1],t)];}
function circleRect(cx,cy,r,rx,ry,hw,hh){
  const dx=Math.abs(cx-rx),dy=Math.abs(cy-ry);
  if(dx>hw+r||dy>hh+r) return false;
  if(dx<=hw||dy<=hh) return true;
  const px=dx-hw,py=dy-hh; return px*px+py*py<=r*r;
}
function circleCircle(x1,y1,r1,x2,y2,r2){
  const dx=x1-x2,dy=y1-y2,rr=r1+r2; return dx*dx+dy*dy<=rr*rr;
}
function roundRect(x,y,w,h,r){
  ctx.beginPath();
  ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y); ctx.arcTo(x+w,y,x+w,y+r,r);
  ctx.lineTo(x+w,y+h-r); ctx.arcTo(x+w,y+h,x+w-r,y+h,r);
  ctx.lineTo(x+r,y+h); ctx.arcTo(x,y+h,x,y+h-r,r); ctx.lineTo(x,y+r);
  ctx.arcTo(x,y,x+r,y,r); ctx.closePath();
}
function text(s,x,y,color,size,align){
  ctx.fillStyle=color; ctx.font='bold '+size+'px "Courier New",monospace';
  ctx.textAlign=align||'center'; ctx.fillText(s,x,y); ctx.textAlign='left';
}
function badgeLabel(n){
  if(n<=1) return '1'; if(n<=5) return '5'; if(n<=10) return '10';
  if(n<=20) return '20'; if(n<=30) return '30'; return '50';
}
function badgeColor(n){
  if(n<=1) return COL.cyan; if(n<=5) return COL.yellow; if(n<=10) return COL.green;
  if(n<=20) return COL.purple; if(n<=30) return COL.red; return COL.white;
}
function isChallenge(s){ return s===3 || (s-3)%4===0; }

