/* ---------------- audio (Web Audio, synthesized) ---------------- */
let AC=null, master=null, muted=false;
function ensureAudio(){
  if(AC) return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=0.5; master.connect(AC.destination);
  }catch(e){ AC=null; }
}
function tone(f,dur,type,vol,f2){
  if(!AC||muted) return;
  const t=AC.currentTime, o=AC.createOscillator(), g=AC.createGain();
  o.type=type||'square'; o.frequency.setValueAtTime(f,t);
  if(f2) o.frequency.exponentialRampToValueAtTime(Math.max(1,f2),t+dur);
  g.gain.setValueAtTime(0.0001,t);
  g.gain.exponentialRampToValueAtTime(vol||0.25,t+0.01);
  g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
  o.connect(g); g.connect(master); o.start(t); o.stop(t+dur+0.02);
}
function noise(dur,vol,filterFreq){
  if(!AC||muted) return;
  const t=AC.currentTime, n=Math.floor(AC.sampleRate*dur);
  const buf=AC.createBuffer(1,n,AC.sampleRate), d=buf.getChannelData(0);
  for(let i=0;i<n;i++) d[i]=(Math.random()*2-1)*(1-i/n);
  const src=AC.createBufferSource(); src.buffer=buf;
  const g=AC.createGain(); g.gain.value=vol||0.3;
  const f=AC.createBiquadFilter(); f.type='lowpass'; f.frequency.value=filterFreq||1200;
  src.connect(f); f.connect(g); g.connect(master); src.start(t); src.stop(t+dur);
}
function sfx(name){
  if(!AC||muted) return;
  switch(name){
    case 'shot':   tone(900,0.08,'square',0.22,320); break;
    case 'hit':    tone(500,0.05,'square',0.18,760); break;
    case 'boom':   noise(0.35,0.5,1400); tone(180,0.3,'sawtooth',0.18,50); break;
    case 'bossHit':tone(240,0.14,'square',0.25,120); noise(0.12,0.18,900); break;
    case 'beam':   tone(700,0.7,'sine',0.12,180); tone(1050,0.7,'sine',0.06,260); break;
    case 'capture':tone(300,0.5,'sawtooth',0.16,900); break;
    case 'dock':   tone(500,0.12,'square',0.2,900); tone(900,0.12,'square',0.16,1300); break;
    case 'jingle': { const n=[392,523,659,784,1046]; n.forEach((f,i)=>tone(f,0.13,'square',0.2,f)); } break;
  }
}

/* ---------------- input ---------------- */
