/* ---------------- enemies ---------------- */
function slotPos(col,row){
  const cx=FORM_X+formation.swayAmp*Math.sin(formation.swayPhase);
  const s=1+formation.breathAmp*Math.sin(formation.breathPhase);
  const colX=FORM_X+col*FORM_DX;
  const x=cx+(colX-FORM_X)*s;
  const y=FORM_Y0+row*FORM_DY+(FORM_Y0-FORM_Y0)*s;
  return [x,y];
}
function makeEnemy(type,col,row){
  return {type,col,row,x:FORM_X,y:FORM_Y0,state:'entering',
    path:null,pathT:0,pathDur:rand(1.4,2.2),wing:0,wingTimer:rand(0,0.5),
    hp:type==='boss'?2:1,diving:false,escort:false,captive:null,beam:null,
    beamPhase:0,beamTimer:0,holdTimer:0,fireTimer:rand(0.5,2),returning:false,
    retPath:null,retT:0,retDur:1.2,alive:true,dead:false,free:false,hostile:false,
    freeTimer:0,freePath:null,freeT:0};
}
function buildFormation(){
  enemies=[]; entryQueue=[]; entryTimer=0;
  const rows=[[],[],[],[],[]];
  for(let r=0;r<5;r++) for(let c=-2;c<=2;c++){
    const type=r===0?'boss':(r<=2?'goei':'zako');
    rows[r].push(makeEnemy(type,c,r));
  }
  // entry order: left->right, row0..4 (bosses first, classic)
  for(let r=0;r<5;r++) for(let c=-2;c<=2;c++) entryQueue.push(rows[r][c+2]);
  for(const e of entryQueue) enemies.push(e);
  formation.active=false; formation.swayPhase=0; formation.swayAmp=6; formation.breathAmp=0; formation.target=0;
}
function buildChallenge(){
  enemies=[]; challenge={active:true,wave:0,spawnTimer:0.4,alive:0,total:0,hits:0,perfect:true};
}
function spawnChallengeWave(){
  const cx=112;
  for(let i=0;i<8;i++){
    const type=i<2?'boss':(i<4?'goei':'zako');
    const e=makeEnemy(type,0,0);
    e.state='flythrough'; e.captive=null; e.escort=false; e.beam=null;
    e.pathT=0; e.pathDur=2.1;
    const side=i%2===0?1:-1;
    e.loop={cx,cy:rand(70,150),r:rand(42,62),phase:i*0.8,side,spd:rand(1.5,2.2)};
    e.x=side>0?112:112; e.y=-14; enemies.push(e);
  }
}
function flythroughPos(e){
  const a=e.loop.phase+e.pathT*e.loop.spd;
  const x=e.loop.cx+e.loop.side*e.loop.r*Math.cos(a);
  const y=e.loop.cy+e.loop.r*Math.sin(a);
  return [x,y];
}
function entryPath(e){
  const col=e.col;
  const sx=col<0?rand(-30,-10):(col===0?rand(80,140):rand(214,254));
  const sy=-16;
  const midx=clamp(FORM_X+col*rand(20,45),20,204);
  const midy=rand(70,150);
  return [[sx,sy],[midx,midy],[FORM_X+col*rand(4,10),FORM_Y0+e.row*FORM_DY-10],[FORM_X+col*FORM_DX,FORM_Y0+e.row*FORM_DY]];
}
function updateEnemies(dt){
  let entering=0, alive=0;
  // spawn from entry queue
  if(entryTimer>0){
    entryTimer-=dt;
    if(entryTimer<=0 && entryQueue.length){
      const e=entryQueue.shift();
      e.path=entryPath(e); e.pathT=0;
      e.x=e.path[0][0]; e.y=e.path[0][1]; e.state='entering';
      entryTimer=rand(0.12,0.32);
    }
  }
  for(const e of enemies){
    if(e.dead) continue;
    if(e.state==='flythrough'){
      e.pathT+=dt/e.pathDur; alive++;
      if(e.pathT>=1){ e.dead=true; continue; }
      const p=flythroughPos(e); e.x=p[0]; e.y=p[1];
      updateWing(e,dt); continue;
    }
    if(e.state==='entering'){
      entering++; alive++;
      e.pathT+=dt/e.pathDur;
      const p=catmull2(e.path[0],e.path[1],e.path[2],e.path[3],clamp(e.pathT,0,1));
      e.x=p[0]; e.y=p[1];
      updateWing(e,dt);
      if(e.state!=='entering') continue;
      if(e.pathT>=1){ e.state='formation'; const sp=slotPos(e.col,e.row); e.x=sp[0]; e.y=sp[1]; }
      // may fire while entering
      e.fireTimer-=dt;
      if(e.fireTimer<=0 && e.y>30 && e.y<200){ enemyFire(e); e.fireTimer=rand(1.5,3.5); }
      continue;
    }
    if(e.state==='formation'){
      alive++;
      const sp=slotPos(e.col,e.row);
      if(e.free){ // freed captive flying down to dock
        e.freeTimer-=dt;
        if(e.freeTimer<=0){ e.free=false; dockCaptive(e); }
        else { e.y+=150*dt; e.x=clamp(e.x,10,GW-10); }
        continue;
      }
      if(e.hostile){ e.x=sp[0]; e.y=sp[1]; e.fireTimer-=dt; if(e.fireTimer<=0){ enemyFire(e); e.fireTimer=rand(1.5,3); } continue; }
      e.x=sp[0]; e.y=sp[1];
      updateWing(e,dt);
      e.fireTimer-=dt;
      if(e.fireTimer<=0){ enemyFire(e); e.fireTimer=rand(2,4); }
      continue;
    }
    if(e.state==='diving'){
      alive++;
      if(e.beam){ updateBeam(e,dt); updateWing(e,dt); continue; }
      e.pathT+=dt/e.pathDur;
      if(e.pathT>=1){ e.state='returning'; e.retT=0; e.retDur=1.1; e.returning=true; }
      else { const p=catmull2(e.path[0],e.path[1],e.path[2],e.path[3],clamp(e.pathT,0,1)); e.x=p[0]; e.y=p[1]; }
      updateWing(e,dt);
      e.fireTimer-=dt;
      if(e.fireTimer<=0){ enemyFire(e); e.fireTimer=rand(0.7,1.6); }
      continue;
    }
    if(e.state==='returning'){
      alive++;
      e.retT+=dt/e.retDur;
      if(e.retT>=1){ e.state='formation'; const sp=slotPos(e.col,e.row); e.x=sp[0]; e.y=sp[1]; e.diving=false; e.escort=false; }
      else { const sp=slotPos(e.col,e.row); e.x=lerp(e.x,sp[0],clamp(e.retT,0,1)); e.y=lerp(e.y,sp[1],clamp(e.retT,0,1)); }
      updateWing(e,dt);
      continue;
    }
  }
  // formation sway / breathing
  if(formation.active){
    formation.swayPhase+=formation.swaySpeed*dt;
    formation.breathPhase+=formation.breathSpeed*dt;
    formation.breathAmp=lerp(formation.breathAmp,0.14,dt*2);
  } else {
    formation.swayPhase+=formation.swaySpeed*dt;
    formation.swayAmp=lerp(formation.swayAmp,6,dt*1.5);
  }
  // dive scheduling
  if(readyTimer<=0 && state==='play' && enemies.some(e=>e.state==='formation')){
    formation.target-=dt;
    if(formation.target<=0){ scheduleDive(); formation.target=clamp(2.4-stage*0.15,0.7,2.4); }
  }
}
function updateWing(e,dt){ e.wingTimer-=dt; if(e.wingTimer<=0){ e.wing^=1; e.wingTimer=0.28; } }
function enemyFire(e){
  if(state!=='play') return;
  const tx=player?player.x:e.x, ty=player?player.y:e.y;
  const dx=tx-e.x, dy=ty-e.y, d=Math.hypot(dx,dy)||1;
  const sp=150;
  ebullets.push({x:e.x,y:e.y,vx:dx/d*sp,vy:dy/d*sp});
}
function scheduleDive(){
  const form=enemies.filter(e=>e.state==='formation'&&!e.hostile&&!e.free);
  if(!form.length) return;
  const e=form[randInt(0,form.length-1)];
  if(e.type==='boss'){
    if(e.captive){ startCaptureDive(e); return; }
    if(Math.random()<0.45) startCaptureDive(e); else startAttackDive(e);
  } else startAttackDive(e);
}
function divePath(e,beamMode){
  const col=e.col;
  const midx=clamp(FORM_X+col*rand(22,42),20,204);
  const midy=rand(90,150);
  const endx=clamp(player?player.x+rand(-40,40):FORM_X+rand(-60,60),14,210);
  const endy=GH+14;
  return [[e.x,e.y],[midx,midy],[endx,endy],[endx,endy]];
}
function startAttackDive(e){
  e.state='diving'; e.diving=true; e.pathT=0; e.pathDur=rand(2.2,3.2); e.path=divePath(e,false); e.fireTimer=rand(0.3,1.0);
  // escorts for boss
  if(e.type==='boss'){
    const goe=enemies.filter(g=>g.state==='formation'&&g.type==='goei');
    const n=randInt(0,2);
    for(let i=0;i<n&&goe.length;i++){
      const g=goe.splice(randInt(0,goe.length-1),1)[0];
      g.state='diving'; g.diving=true; g.escort=true; g.pathT=0; g.pathDur=e.pathDur; g.path=e.path; g.fireTimer=rand(0.5,1.2);
    }
  }
}
function startCaptureDive(e){
  e.state='diving'; e.diving=true; e.beamPhase=0; e.beamTimer=0; e.holdTimer=0;
  const col=e.col;
  const midx=clamp(FORM_X+col*rand(20,40),20,204);
  const midy=rand(90,130);
  const holdY=rand(120,175);
  e.path=[[e.x,e.y],[midx,midy],[midx,holdY],[midx,holdY]];
  e.pathT=0; e.pathDur=1.6;
}
function updateBeam(e,dt){
  e.pathT+=dt/e.pathDur;
  if(e.pathT<1){ const p=catmull2(e.path[0],e.path[1],e.path[2],e.path[3],clamp(e.pathT,0,1)); e.x=p[0]; e.y=p[1]; }
  else {
    const p=e.path[3]; e.x=p[0]; e.y=p[1];
    e.beamPhase+=dt;
    if(e.beamPhase>0.4 && !e.beam){ e.beam=true; sfx('beam'); }
    if(e.beam){
      e.beamTimer+=dt;
      if(player&&player.alive&&!player.captured&&!player.dying){
        if(player.x>e.x-14&&player.x<e.x+14&&player.y<e.y){ capturePlayer(e); }
      }
      if(e.beamTimer>4.5){ e.beam=false; e.holdTimer+=dt; if(e.holdTimer>1.2){ e.state='returning'; e.retT=0; e.retDur=1.2; e.beam=null; } }
    }
  }
  // captive fires while boss dives
  if(e.captive&&e.captive.alive&&Math.random()<dt*0.8){ enemyFire(e.captive); }
}
function capturePlayer(e){
  if(player.dying) return;
  player.captured=true; player.captureBoss=e; sfx('capture');
  const sp=slotPos(e.col,e.row);
  e.captive={alive:true,type:'captive',x:sp[0],y:sp[1],slotCol:e.col,slotRow:e.row,hostile:false};
  player.dying=true; player.deathTimer=0.55; player.deathExp=true;
  sfx('boom');
}
function dockCaptive(e){
  if(!player||!player.alive||player.dying){ return; }
  player.dual=true; sfx('dock');
}
function bossValue(e){
  let escorts=0;
  for(const o of enemies){ if(o!==e&&o.diving&&o.escort&&o.type==='goei'&&o.alive) escorts++; }
  if(escorts>=2) return 1600; if(escorts===1) return 400; return 800;
}
function enemyValue(e){
  if(e.type==='boss') return bossValue(e);
  if(e.type==='goei') return e.diving?160:80;
  return e.diving?100:50;
}

/* ---------------- player ---------------- */
function initPlayer(){
  player={x:112,y:PLAYER_Y,alive:true,dying:false,deathTimer:0,deathExp:false,
    captured:false,captureBoss:null,dual:false,invuln:1.5,shots:0,fireCooldown:0,flash:0};
}
function updatePlayer(dt){
  if(!player) return;
  if(player.dying){
    player.deathTimer-=dt;
    if(player.deathTimer<=0) finishPlayerDeath();
    return;
  }
  player.invuln=Math.max(0,player.invuln-dt);
  if(readyTimer>0) return;   // locked during READY
  if(keys.left) player.x-=PLAYER_SPEED*dt;
  if(keys.right) player.x+=PLAYER_SPEED*dt;
  player.x=clamp(player.x,14,GW-14);
  player.fireCooldown=Math.max(0,player.fireCooldown-dt);
  if(keys.space&&player.fireCooldown<=0&&player.shots<MAX_SHOTS){
    firePlayer();
  }
}
function firePlayer(){
  player.fireCooldown=0.28;
  const half=player.dual?10:7;
  shots.push({x:player.x-half,y:player.y-12,vy:-320});
  if(player.dual){ shots.push({x:player.x+half,y:player.y-12,vy:-320}); }
  player.shots++; shotsFired++; sfx('shot');
}
function killPlayer(){
  if(player.dying) return;
  player.dying=true; player.deathTimer=0.55; player.deathExp=true; sfx('boom');
}
function finishPlayerDeath(){
  player.dying=false; player.captured=false; player.dual=false; player.captureBoss=null;
  // clear any beam holding this ship
  if(player.deathExp){ explosions.push({x:player.x,y:player.y,t:0,type:'player'}); player.deathExp=false; }
  ships--;
  if(ships<0){ state='gameover'; gameOverTimer=2.2; return; }
  player.alive=true; player.x=112; player.invuln=1.5; player.shots=0;
  respawnTimer=1.0; readyTimer=1.0;
}

/* ---------------- projectiles & collisions ---------------- */
function updateShots(dt){
  for(const s of shots){ s.y+=s.vy*dt; }
  shots=shots.filter(s=>{ if(s.y<-8){ if(player) player.shots--; return false; } return true; });
}
function updateEbullets(dt){
  for(const b of ebullets){ b.x+=b.vx*dt; b.y+=b.vy*dt; }
  ebullets=ebullets.filter(b=>b.x>-6&&b.x<GW+6&&b.y>-6&&b.y<GH+6);
}
function resolveCollisions(){
  // player shots vs enemies
  for(const s of shots){
    for(const e of enemies){
      if(e.dead||e.free||!e.alive) continue;
      if(e.type==='captive') continue;
      const r=e.type==='boss'?11:8;
      if(circleRect(s.x,s.y,2,e.x,e.y,r,r)){
        s.dead=true; if(player) player.shots--; shotsHit++;
        if(e.type==='boss'){
          e.hp--; sfx('bossHit');
          if(e.hp<=0){
            addScore(enemyValue(e));
            if(e.captive&&e.captive.alive){
              if(e.diving){ // freed -> docks
                e.captive.free=true; e.captive.freeTimer=1.2; e.captive.x=e.x; e.captive.y=e.y; e.captive.dead=false;
              } else { // in formation -> destroyed
                explosions.push({x:e.captive.x,y:e.captive.y,t:0,type:'enemy'}); e.captive.alive=false; e.captive=null;
              }
            }
            explosions.push({x:e.x,y:e.y,t:0,type:'enemy'}); e.dead=true; sfx('boom');
          }
        } else {
          addScore(enemyValue(e));
          explosions.push({x:e.x,y:e.y,t:0,type:'enemy'}); e.dead=true; sfx('boom');
        }
        break;
      }
    }
  }
  shots=shots.filter(s=>!s.dead);
  // challenge scoring
  if(challenge.active){
    for(const e of enemies){ if(e.dead&&!e.counted){ e.counted=true; challenge.hits++; addScore(100); } }
  }
  // enemy bullets vs player
  if(player&&player.alive&&!player.dying&&player.invuln<=0){
    for(const b of ebullets){
      if(player.dual){
        const hitL=circleRect(b.x,b.y,2,player.x-10,player.y,7,9);
        const hitR=circleRect(b.x,b.y,2,player.x+10,player.y,7,9);
        if(hitL||hitR){ b.dead=true; killPlayer(); break; }
      } else {
        if(circleRect(b.x,b.y,2,player.x,player.y,PLAYER_HALF,9)){ b.dead=true; killPlayer(); break; }
      }
    }
    ebullets=ebullets.filter(b=>!b.dead);
  }
  // player vs enemies (ram)
  if(player&&player.alive&&!player.dying&&player.invuln<=0){
    for(const e of enemies){
      if(e.dead||e.free||!e.alive) continue;
      const r=e.type==='boss'?11:8;
      const hit=player.dual
        ? (circleRect(player.x-10,player.y,r,player.x-10,player.y,7,9)||circleRect(player.x+10,player.y,r,player.x+10,player.y,7,9))
        : circleRect(player.x,player.y,r,player.x,player.y,PLAYER_HALF,9);
      if(hit){
        if(e.type==='boss'){ e.hp--; if(e.hp<=0){ addScore(enemyValue(e)); explosions.push({x:e.x,y:e.y,t:0,type:'enemy'}); e.dead=true; sfx('boom'); } else sfx('bossHit'); }
        else { addScore(enemyValue(e)); explosions.push({x:e.x,y:e.y,t:0,type:'enemy'}); e.dead=true; sfx('boom'); }
        killPlayer(); break;
      }
    }
  }
  // captive vs enemy bullets
  for(const e of enemies){
    if(e.captive&&e.captive.alive){
      for(const b of ebullets){
        if(circleRect(b.x,b.y,2,e.captive.x,e.captive.y,7,7)){ b.dead=true; explosions.push({x:e.captive.x,y:e.captive.y,t:0,type:'enemy'}); e.captive.alive=false; e.captive=null; }
      }
    }
  }
  ebullets=ebullets.filter(b=>!b.dead);
  enemies=enemies.filter(e=>!e.dead);
}
function addScore(n){
  score+=n;
  if(score>high){ high=score; localStorage.setItem('galaga_high',String(high)); }
  while(score>=nextExtra){ ships++; nextExtra+=EXTRA_STEP; }
}

/* ---------------- explosions / particles ---------------- */
function updateEffects(dt){
  for(const ex of explosions){ ex.t+=dt; }
  explosions=explosions.filter(e=>e.t<0.45);
  for(const p of particles){ p.x+=p.vx*dt; p.y+=p.vy*dt; p.life-=dt; }
  particles=particles.filter(p=>p.life>0);
}
function drawExplosion(ex){
  const cx=ex.x,cy=ex.y;
  const f=ex.type==='player'?7:6;
  const rings=[
    {r:6,color:COL.white,from:0,to:0.14},
    {r:10,color:COL.yellow,from:0.08,to:0.24},
    {r:14,color:COL.red,from:0.18,to:0.36},
    {r:18,color:COL.orange,from:0.3,to:0.45}
  ];
  for(const ring of rings){
    if(ex.t<ring.from||ex.t>ring.to) continue;
    const p=(ex.t-ring.from)/(ring.to-ring.from);
    const rad=ring.r*(0.5+p);
    ctx.strokeStyle=ring.color; ctx.lineWidth=1;
    for(let i=0;i<f;i++){
      const a=(i/f)*6.283+p*0.8;
      ctx.beginPath();
      ctx.moveTo(cx+Math.cos(a)*rad*0.4,cy+Math.sin(a)*rad*0.4);
      ctx.lineTo(cx+Math.cos(a)*rad,cy+Math.sin(a)*rad);
      ctx.stroke();
    }
  }
}

/* ---------------- rendering ---------------- */
function drawBackground(){
  ctx.fillStyle='#000'; ctx.fillRect(0,0,GW,GH);
  for(const s of stars){
    const a=0.5+0.5*Math.sin(time*s.twSpd+s.tw);
    ctx.globalAlpha=0.4+0.6*a; ctx.fillStyle=s.color;
    ctx.fillRect(s.x|0,s.y|0,s.size,s.size);
  }
  ctx.globalAlpha=1;
}
function updateStars(dt){
  for(const s of stars){ s.y+=s.spd*dt; if(s.y>GH){ s.y=0; s.x=rand(0,GW); } }
}
function drawHUD(){
  text('1UP',30,12,COL.red,10,'left');
  text(String(score).padStart(6,'0'),30,24,COL.white,10,'left');
  text('HIGH SCORE',112,12,COL.red,10,'center');
  text(String(high).padStart(6,'0'),112,24,COL.white,10,'center');
  // reserve ships
  for(let i=0;i<ships;i++) drawSprite(SPR.player,14+i*16,GH-16,COL.cyan);
  // stage badges
  const n=Math.min(stage,BADGE.length);
  for(let i=0;i<n;i++){
    const bx=GW-10-i*11; drawFlag(bx,GH-14,badgeColor(BADGE[i]));
  }
}
function drawPlayer(){
  if(!player||!player.alive) return;
  if(player.dying) return;
  const blink=player.invuln>0 && Math.floor(time*12)%2===0;
  if(blink) return;
  const spr=player.shots>0?SPR.playerOpen:SPR.player;
  if(player.dual){
    drawSprite(spr,player.x-17,player.y-8,COL.cyan);
    drawSprite(spr,player.x+3,player.y-8,COL.cyan);
  } else {
    drawSprite(spr,player.x-7,player.y-8,COL.cyan);
  }
}
function drawCaptives(){
  for(const e of enemies){
    if(e.captive&&e.captive.alive){
      const sp=slotPos(e.captive.slotCol,e.captive.slotRow);
      e.captive.x=sp[0]; e.captive.y=sp[1];
      drawSprite(SPR.capt,e.captive.x-7,e.captive.y-6,COL.red);
    }
  }
}
function drawEnemies(){
  for(const e of enemies){
    if(e.dead) continue;
    if(e.type==='captive') continue;
    let color;
    if(e.type==='zako') color=COL.cyan;
    else if(e.type==='goei') color=COL.red;
    else color=(e.hp===2)?COL.green:COL.purple;
    let spr;
    if(e.type==='zako') spr=e.wing?SPR.beeOpen:SPR.bee;
    else if(e.type==='goei') spr=e.wing?SPR.butterflyOpen:SPR.butterfly;
    else spr=e.wing?SPR.bossOpen:SPR.boss;
    const w=spr[0].length, h=spr.length;
    drawSprite(spr,e.x-w/2,e.y-h/2,color);
  }
}
function drawBeams(){
  for(const e of enemies){
    if(e.beam){
      const bx=e.x, by=e.y+6;
      for(let i=0;i<6;i++){
        const a=0.12+0.12*i+Math.sin(time*10+i)*0.05;
        ctx.globalAlpha=0.16; ctx.fillStyle=COL.blueLight;
        ctx.beginPath(); ctx.moveTo(bx,by);
        ctx.lineTo(bx-Math.tan(a)*(GH-by),GH);
        ctx.lineTo(bx+Math.tan(a)*(GH-by),GH);
        ctx.closePath(); ctx.fill();
      }
      ctx.globalAlpha=1;
    }
  }
}
function drawShots(){
  ctx.fillStyle=COL.white;
  for(const s of shots) ctx.fillRect(s.x-1,s.y-4,2,8);
}
function drawEbullets(){
  for(const b of ebullets){
    ctx.fillStyle=COL.white; ctx.fillRect(b.x-1,b.y-3,2,3);
    ctx.fillStyle=COL.yellow; ctx.fillRect(b.x-1,b.y,2,3);
  }
}
function drawEffects(){ for(const ex of explosions) drawExplosion(ex); }
function drawMessage(s,x,y,color,size){ text(s,x,y,color,size,'center'); }

function drawTitle(){
  drawBackground();
  // title logo
  ctx.fillStyle='#000'; ctx.fillRect(0,0,GW,GH);
  drawBackground();
  // "GALAGA" in arcade-ish stacked colours
  const title='GALAGA';
  ctx.font='bold 30px "Courier New",monospace'; ctx.textAlign='center';
  ctx.fillStyle=COL.cyan; ctx.fillText(title,112,52);
  ctx.fillStyle=COL.yellow; ctx.fillText(title,112,54);
  ctx.fillStyle=COL.cyan; ctx.fillText(title,112,53);
  // score table
  const rows=[
    ['ZAKO',50,100,COL.cyan,SPR.bee],
    ['GOEI',80,160,COL.red,SPR.butterfly],
    ['BOSS',150,800,COL.green,SPR.boss]
  ];
  text('1UP SCORE',40,96,COL.red,10,'left');
  let y=112;
  for(const r of rows){
    drawSprite(r[4],30,y-8,r[3]);
    text(r[0],60,y+4,COL.white,10,'left');
    text(String(r[1]),120,y+4,COL.white,10,'left');
    text(String(r[2]),160,y+4,COL.white,10,'left');
    y+=26;
  }
  text('FORMATION',120,100,COL.white,9,'left');
  text('DIVING',160,100,COL.white,9,'left');
  text('HIGH SCORE  '+high,112,196,COL.yellow,10,'center');
  if(Math.floor(titleT*2)%2===0) drawMessage('PRESS ENTER TO START',112,236,COL.cyan,12);
  drawMessage('ARROWS/A D  MOVE   SPACE  FIRE',112,258,COL.white,9);
  drawMessage('ENTER START   P PAUSE   M MUTE',112,272,COL.white,9);
  ctx.textAlign='left';
}
function drawStageIntro(){
  drawBackground(); drawHUD();
  drawMessage('STAGE '+stage,112,150,COL.yellow,22);
  if(isChallenge(stage)) drawMessage('CHALLENGING STAGE',112,172,COL.cyan,11);
}
function drawPlay(){
  drawBackground();
  drawBeams();
  drawCaptives();
  drawEnemies();
  drawPlayer();
  drawShots();
  drawEbullets();
  drawEffects();
  drawHUD();
  if(readyTimer>0) drawMessage('READY',112,150,COL.yellow,18);
  if(respawnTimer>0&&readyTimer<=0) drawMessage('READY',112,150,COL.yellow,18);
}
function drawChallengeIntro(){
  drawBackground(); drawHUD();
  drawMessage('CHALLENGING STAGE',112,140,COL.cyan,16);
  drawMessage('STAGE '+stage,112,164,COL.yellow,12);
}
function drawChallenge(){
  drawBackground();
  drawEnemies(); drawPlayer(); drawShots(); drawEffects(); drawHUD();
  drawMessage('CHALLENGING STAGE',112,150,COL.cyan,14);
}
function drawChallengeResults(){
  drawBackground(); drawHUD();
  drawMessage('NUMBER OF HITS',112,120,COL.yellow,14);
  drawMessage(String(challengeHits),112,142,COL.white,18);
  drawMessage('BONUS',112,172,COL.cyan,12);
  drawMessage(String(challengeBonus),112,192,COL.white,16);
  if(challengePerfect) drawMessage('PERFECT!',112,214,COL.red,16);
}
function drawStageClear(){
  drawBackground(); drawHUD();
  drawMessage('STAGE '+stage+' CLEAR',112,150,COL.yellow,18);
}
function drawGameOver(){
  drawBackground(); drawHUD();
  drawMessage('GAME OVER',112,120,COL.red,22);
  drawMessage('SHOTS FIRED   '+shotsFired,112,150,COL.white,11);
  drawMessage('HITS          '+shotsHit,112,166,COL.white,11);
  const ratio=shotsFired?Math.round(shotsHit/shotsFired*100):0;
  drawMessage('HIT RATIO     '+ratio+'%',112,182,COL.white,11);
  drawMessage('HIGH SCORE    '+high,112,200,COL.yellow,11);
  if(Math.floor(time*2)%2===0) drawMessage('PRESS ENTER TO START',112,236,COL.cyan,11);
}

/* ---------------- state transitions ---------------- */
function startNewGame(){
  stage=1; score=0; ships=3; shotsFired=0; shotsHit=0; nextExtra=EXTRA_FIRST;
  shots=[]; ebullets=[]; explosions=[]; particles=[];
  initPlayer(); startStage();
}
function startStage(){
  shots=[]; ebullets=[]; explosions=[];
  initPlayer();
  if(isChallenge(stage)){ state='challengeIntro'; timer=1.8; }
  else { state='stageIntro'; timer=1.8; }
}
function beginPlayStage(){
  buildFormation();
  state='play'; readyTimer=1.0; respawnTimer=1.0;
  sfx('jingle');
}
function beginChallengeStage(){
  buildChallenge();
  state='challenge'; timer=0; sfx('jingle');
}
function endChallenge(){
  challengeBonus=0; challengePerfect=challenge.perfect;
  // wave bonuses
  const waves=Math.floor(challenge.hits/8);
  challengeBonus+=waves*1000;
  if(challenge.hits>=40){ challengeBonus+=10000; challengePerfect=true; }
  addScore(challengeBonus);
  state='challengeResults'; timer=3.2;
}
function nextStage(){ stage++; startStage(); }

/* ---------------- update (state machine) ---------------- */
function update(dt){
  time+=dt; titleT+=dt; blink+=dt;
  updateStars(dt);
  if(keys.space===undefined) keys.space=false;
  switch(state){
    case 'title': break;
    case 'stageIntro':
      timer-=dt; if(timer<=0) beginPlayStage(); break;
    case 'challengeIntro':
      timer-=dt; if(timer<=0) beginChallengeStage(); break;
    case 'play':
      if(readyTimer>0){ readyTimer-=dt; }
      if(respawnTimer>0){ respawnTimer-=dt; }
      updatePlayer(dt);
      updateEnemies(dt);
      updateShots(dt); updateEbullets(dt);
      resolveCollisions();
      updateEffects(dt);
      if(enemies.length===0 && entryQueue.length===0 && !player.dying){
        state='stageClear'; stageClearTimer=2.4;
      }
      break;
    case 'challenge':
      updatePlayer(dt);
      updateEnemies(dt);
      updateShots(dt); updateEbullets(dt);
      resolveCollisions();
      updateEffects(dt);
      challenge.spawnTimer-=dt;
      if(challenge.spawnTimer<=0 && challenge.wave<5){
        spawnChallengeWave(); challenge.wave++; challenge.spawnTimer=2.4;
      }
      if(challenge.wave>=5 && enemies.length===0){ endChallenge(); }
      break;
    case 'challengeResults':
      timer-=dt; if(timer<=0) nextStage(); break;
    case 'stageClear':
      stageClearTimer-=dt; if(stageClearTimer<=0) nextStage(); break;
    case 'gameOver':
      updateEffects(dt);
      gameOverTimer-=dt;
      if(gameOverTimer<=0){ state='title'; }
      break;
  }
}

/* ---------------- render dispatch ---------------- */
function render(){
  ctx.setTransform(SCALE*DPR,0,0,SCALE*DPR,0,0);
  switch(state){
    case 'title': drawTitle(); break;
    case 'stageIntro': drawStageIntro(); break;
    case 'play': drawPlay(); break;
    case 'challengeIntro': drawChallengeIntro(); break;
    case 'challenge': drawChallenge(); break;
    case 'challengeResults': drawChallengeResults(); break;
    case 'stageClear': drawStageClear(); break;
    case 'gameOver': drawGameOver(); break;
  }
}

/* ---------------- fixed-timestep loop ---------------- */
let last=performance.now(), acc=0, paused=false;
function togglePause(){ if(state==='play') paused=!paused; }
function frame(now){
  requestAnimationFrame(frame);
  let dt=(now-last)/1000; last=now;
  if(dt>0.25) dt=0.25;
  if(!paused) acc+=dt;
  while(acc>=STEP){ update(STEP); acc-=STEP; }
  render();
}
requestAnimationFrame(frame);
</script>
</body>
</html>
```

Notes on what I did **not** fully implement:

- **Enemy bullets are aimed at the player** rather than straight down (the arcade fires downward); this is a fairness choice but changes the feel slightly.
- **Dual fighter width** is approximate (two ships ~14px apart with a small gap); I did not model the exact arcade "twice the width, ships nearly touching" geometry.
- **Captured-fighter behavior**: the captive is drawn in the boss's formation slot and fires when the boss dives, but I do not animate it being physically dragged up into the beam, nor a dedicated "captive turns hostile and joins the enemy formation" state after the in-formation boss kill (it is simply destroyed there).
- **Boss dive value tiers** (800 / 400 / 1600) are counted from escorts that are currently diving, which is close to but not a strict arcade replication of the escort pairing logic.
- **Challenging-stage entry waves** use looping flight paths through the field (not the exact arcade choreography), and the 1,000-per-wave bonus is derived from total hits rather than tracked per discrete wave.
- **Stage badges** show the denomination of the current stage (1, 5, 10, 20, 30, 50) rather than a row of historical badges.
